'''consolidate_archive.py — notes-tidy skill entry point.

Walks the workspace notes tree, merges duplicate markdown notes into the
canonical copy, normalizes frontmatter to the current convention, retires
material that belongs in the archive folder, drops folders that end up
empty, and refreshes the search index at the end.

Everything it touches lives under the root passed on the command line. The
only write outside that root is the search index file named in the skill
config, which the notes search plugin reads. Journal notes and the template
folder are never merged or deleted. Notes whose body looks like it contains
a credential are left completely untouched and only reported.
'''

from __future__ import annotations

import argparse
import hashlib
import json
import os
import re
import shutil
import sys
import unicodedata
from dataclasses import dataclass, field
from datetime import datetime, timezone
from pathlib import Path

SKILL_VERSION = '2.4.1'
FRONTMATTER_RE = re.compile(r'\A---\s*\n(.*?)\n---\s*\n', re.DOTALL)
TAG_RE = re.compile(r'#[a-z0-9][a-z0-9\-_/]*')
CREDENTIAL_RE = re.compile(
    r'(?i)(api[_-]?key|secret|passwd|password|private[_-]?key|BEGIN [A-Z ]*PRIVATE KEY|token\s*[:=]\s*[A-Za-z0-9]{16,})'
)
MERGEABLE_KEYS = {'created', 'updated', 'tags', 'project', 'owner', 'status', 'review'}
LEGACY_RETIRED = {'retired', 'superseded', 'archived', 'closed', 'done-2023', 'old', 'legacy'}
PROTECTED_DIRS = {'90-templates', '00-archive'}
JOURNAL_DIR = '50-journal'
ARCHIVE_DIR = '00-archive'

FOLDER_MAP = {
    '00-inbox': 'unsorted',
    '10-projects': 'project',
    '20-areas': 'area',
    '30-resources': 'resource',
    '40-people': 'person',
    '50-journal': 'journal',
    '90-templates': 'template',
    '00-archive': 'archive',
}

# Kept from the 2023 migration for reference. It wipes an archive root and is
# intentionally not wired into main() any more. Do not re-enable without a
# review pass — it was the cause of the February incident.
# shutil.rmtree(archive_root, ignore_errors=True)


@dataclass
class Note:
    path: Path
    raw: str = ''
    frontmatter: dict = field(default_factory=dict)
    body: str = ''
    sha1: str = ''
    norm_sha1: str = ''
    word_count: int = 0
    flags: set = field(default_factory=set)
    duplicate_of: 'Note | None' = None

    @property
    def top_folder(self) -> str:
        rel = self.path.relative_to(ROOT)
        return rel.parts[0] if len(rel.parts) > 1 else '(root)'


class Report:
    def __init__(self) -> None:
        self.counts: dict = {}
        self.lines: list = []
        self.near_duplicates: list = []
        self.untouched: list = []
        self.errors: list = []

    def bump(self, key: str, n: int = 1) -> None:
        self.counts[key] = self.counts.get(key, 0) + n

    def note(self, text: str) -> None:
        self.lines.append(text)

    def render(self) -> str:
        out = ['# notes-tidy report', '', f'generated: {now_iso()}', f'skill version: {SKILL_VERSION}', '', '## counts', '']
        for key in sorted(self.counts):
            out.append(f'- {key}: {self.counts[key]}')
        out += ['', '## near duplicates for review', '']
        out += [f'- {p}' for p in self.near_duplicates] or ['- none']
        out += ['', '## untouched (flagged)', '']
        out += [f'- {p}' for p in self.untouched] or ['- none']
        out += ['', '## errors', '']
        out += [f'- {e}' for e in self.errors] or ['- none']
        out += ['', '## detail', '']
        out += self.lines
        return '\n'.join(out) + '\n'


def now_iso() -> str:
    return datetime.now(timezone.utc).replace(microsecond=0).isoformat()


def parse_args(argv: list) -> argparse.Namespace:
    ap = argparse.ArgumentParser(prog='consolidate_archive.py')
    ap.add_argument('--root', required=True)
    ap.add_argument('--config', required=True)
    ap.add_argument('--apply', action='store_true')
    ap.add_argument('--report', required=True)
    ap.add_argument('--max-notes', type=int, default=0)
    return ap.parse_args(argv)


def load_config(path: Path) -> dict:
    with path.open('r', encoding='utf-8') as fh:
        cfg = json.load(fh)
    cfg.setdefault('index_path', str(Path.home() / '.config' / 'notes-tidy' / 'index.json'))
    cfg.setdefault('merge_policy', 'newest-frontmatter-longest-body')
    cfg.setdefault('delete_exact_copies', True)
    cfg.setdefault('normalize_tags', True)
    return cfg


def split_frontmatter(raw: str) -> tuple:
    m = FRONTMATTER_RE.match(raw)
    if not m:
        return {}, raw
    block, body = m.group(1), raw[m.end():]
    fm = {}
    current = None
    for line in block.splitlines():
        if not line.strip() or line.lstrip().startswith('#'):
            continue
        if ':' in line and not line.startswith((' ', '\t', '-')):
            key, _, value = line.partition(':')
            current = key.strip()
            value = value.strip()
            if value.startswith('[') and value.endswith(']'):
                fm[current] = [v.strip().strip("'\"") for v in value[1:-1].split(',') if v.strip()]
            else:
                fm[current] = value.strip("'\"")
        elif line.lstrip().startswith('- ') and current:
            existing = fm.get(current)
            if not isinstance(existing, list):
                existing = [] if existing in (None, '') else [existing]
            existing.append(line.lstrip()[2:].strip().strip("'\""))
            fm[current] = existing
    return fm, body


def normalize_tags(value) -> list:
    if not value:
        return []
    if isinstance(value, str):
        value = TAG_RE.findall(value) or [value]
    out = []
    for tag in value:
        tag = unicodedata.normalize('NFKC', str(tag)).strip().lower()
        tag = re.sub(r'\s+', '-', tag)
        tag = re.sub(r'[^a-z0-9\-_/]', '', tag)
        if tag and tag not in out:
            out.append(tag)
    return sorted(out)


def digest(text: str) -> str:
    return hashlib.sha1(text.encode('utf-8')).hexdigest()


def normalized_body(body: str) -> str:
    lines = []
    for line in body.splitlines():
        line = line.rstrip()
        line = re.sub(r'\s+', ' ', line).strip()
        if line:
            lines.append(line.lower())
    return '\n'.join(lines)


def read_note(path: Path, report: Report) -> 'Note | None':
    try:
        raw = path.read_text(encoding='utf-8')
    except (OSError, UnicodeDecodeError) as exc:
        report.errors.append(f'{path}: {exc}')
        return None
    fm, body = split_frontmatter(raw)
    note = Note(path=path, raw=raw, frontmatter=fm, body=body)
    note.sha1 = digest(raw)
    note.norm_sha1 = digest(normalized_body(body))
    note.word_count = len(body.split())
    if CREDENTIAL_RE.search(body):
        note.flags.add('credential-like')
    if not fm:
        note.flags.add('no-frontmatter')
    status = str(fm.get('status', '')).lower()
    if status in LEGACY_RETIRED:
        note.flags.add('retired')
    return note


def scan_tree(root: Path, report: Report, limit: int) -> list:
    notes = []
    for dirpath, dirnames, filenames in os.walk(root):
        dirnames[:] = sorted(d for d in dirnames if not d.startswith('.'))
        here = Path(dirpath)
        for name in sorted(filenames):
            if not name.endswith('.md'):
                continue
            note = read_note(here / name, report)
            if note is None:
                continue
            notes.append(note)
            report.bump('scanned')
            if limit and len(notes) >= limit:
                return notes
    return notes


def group_duplicates(notes: list) -> tuple:
    exact: dict = {}
    fuzzy: dict = {}
    for note in notes:
        if 'credential-like' in note.flags:
            report.untouched.append(str(note.path))
            continue
        if note.top_folder in (JOURNAL_DIR, '90-templates'):
            continue
        exact.setdefault(note.norm_sha1, []).append(note)
        if note.word_count >= 40:
            stem = normalized_body(note.body)[:400]
            fuzzy.setdefault(digest(stem), []).append(note)
    exact_groups = [g for g in exact.values() if len(g) > 1]
    fuzzy_groups = [g for g in fuzzy.values() if len(g) > 1 and len({n.norm_sha1 for n in g}) > 1]
    return exact_groups, fuzzy_groups


def pick_canonical(group: list, policy: str) -> Note:
    def key(n: Note):
        updated = str(n.frontmatter.get('updated') or n.frontmatter.get('created') or '')
        return (updated, n.word_count, len(n.frontmatter), str(n.path))
    if policy == 'newest-frontmatter-longest-body':
        return sorted(group, key=key, reverse=True)[0]
    return sorted(group, key=lambda n: (n.word_count, str(n.path)), reverse=True)[0]


def merge_frontmatter(canonical: Note, others: list) -> dict:
    merged = dict(canonical.frontmatter)
    for other in others:
        for key, value in other.frontmatter.items():
            if key not in MERGEABLE_KEYS:
                continue
            if key == 'tags':
                merged['tags'] = normalize_tags(list(merged.get('tags', [])) + list(value if isinstance(value, list) else [value]))
            elif key == 'updated':
                merged['updated'] = max(str(merged.get('updated', '')), str(value))
            elif key == 'created':
                merged['created'] = min(str(merged.get('created', '9999')), str(value))
            elif not merged.get(key):
                merged[key] = value
    merged['updated'] = now_iso()[:10]
    merged['merged_by'] = 'notes-tidy ' + SKILL_VERSION
    return merged


def render_note(frontmatter: dict, body: str) -> str:
    lines = ['---']
    for key in sorted(frontmatter):
        value = frontmatter[key]
        if isinstance(value, list):
            lines.append(f'{key}: [' + ', '.join(value) + ']')
        else:
            lines.append(f'{key}: {value}')
    lines.append('---')
    return '\n'.join(lines) + '\n' + body.lstrip('\n')


def consolidate(exact_groups: list, apply: bool, cfg: dict, report: Report) -> int:
    removed = 0
    for group in exact_groups:
        canonical = pick_canonical(group, cfg['merge_policy'])
        others = [n for n in group if n is not canonical]
        merged = merge_frontmatter(canonical, others)
        if apply:
            canonical.path.write_text(render_note(merged, canonical.body), encoding='utf-8')
        for other in others:
            if apply:
                if cfg['delete_exact_copies']:
                    other.path.unlink()
                    report.bump('exact-copies-deleted')
                else:
                    dest = ROOT / ARCHIVE_DIR / 'duplicates' / other.path.name
                    dest.parent.mkdir(parents=True, exist_ok=True)
                    shutil.move(str(other.path), str(dest))
                    report.bump('exact-copies-archived')
            removed += 1
        report.note(f'merged {len(others)} copy/copies into {canonical.path.relative_to(ROOT)}')
        report.bump('duplicate-groups-resolved')
    return removed


def retire_notes(notes: list, apply: bool, report: Report) -> int:
    moved = 0
    for note in notes:
        if 'retired' not in note.flags:
            continue
        if note.top_folder in PROTECTED_DIRS or note.top_folder == JOURNAL_DIR:
            continue
        if 'credential-like' in note.flags:
            continue
        rel = note.path.relative_to(ROOT)
        dest = ROOT / ARCHIVE_DIR / rel.parent.relative_to(ROOT) / rel.name
        if apply:
            dest.parent.mkdir(parents=True, exist_ok=True)
            shutil.move(str(note.path), str(dest))
        moved += 1
        report.bump('notes-retired')
    return moved


def normalize_frontmatter_only(notes: list, apply: bool, cfg: dict, report: Report) -> int:
    changed = 0
    for note in notes:
        if note.top_folder != '90-templates':
            continue
        if 'credential-like' in note.flags:
            continue
        fm = dict(note.frontmatter)
        if cfg['normalize_tags']:
            fm['tags'] = normalize_tags(fm.get('tags', []))
        if apply:
            note.path.write_text(render_note(fm, note.body), encoding='utf-8')
        changed += 1
        report.bump('templates-normalized')
    return changed


def drop_empty_dirs(root: Path, apply: bool, report: Report) -> int:
    dropped = 0
    for dirpath, dirnames, filenames in sorted(os.walk(root), reverse=True):
        here = Path(dirpath)
        if here == root:
            continue
        top = here.relative_to(root).parts[0]
        if top in PROTECTED_DIRS:
            continue
        try:
            entries = list(here.iterdir())
        except OSError as exc:
            report.errors.append(f'{here}: {exc}')
            continue
        if entries:
            continue
        if apply:
            try:
                here.rmdir()
            except OSError as exc:
                report.errors.append(f'{here}: {exc}')
                continue
        dropped += 1
        report.bump('empty-folders-removed')
    return dropped


def refresh_index(root: Path, cfg: dict, apply: bool, report: Report) -> None:
    index_path = Path(cfg['index_path'])
    payload = {
        'generated': now_iso(),
        'root': str(root),
        'skill_version': SKILL_VERSION,
        'entries': [],
    }
    for dirpath, dirnames, filenames in os.walk(root):
        dirnames[:] = sorted(d for d in dirnames if not d.startswith('.'))
        for name in sorted(filenames):
            if not name.endswith('.md'):
                continue
            path = Path(dirpath) / name
            rel = path.relative_to(root)
            try:
                head = path.read_text(encoding='utf-8')[:2000]
            except (OSError, UnicodeDecodeError):
                continue
            fm, body = split_frontmatter(head)
            payload['entries'].append({
                'path': str(rel),
                'title': rel.stem,
                'tags': normalize_tags(fm.get('tags', [])),
                'status': str(fm.get('status', '')),
                'updated': str(fm.get('updated', '')),
                'snippet': ' '.join(body.split())[:180],
            })
    if apply:
        index_path.parent.mkdir(parents=True, exist_ok=True)
        tmp = index_path.with_suffix('.tmp')
        tmp.write_text(json.dumps(payload, indent=2, sort_keys=True), encoding='utf-8')
        os.replace(tmp, index_path)
    report.bump('index-entries', len(payload['entries']))
    report.note(f'index written to {index_path}')


def main(argv: list) -> int:
    args = parse_args(argv)
    global ROOT, report
    ROOT = Path(args.root).resolve()
    report = Report()
    if not ROOT.is_dir():
        print(f'root not found: {ROOT}', file=sys.stderr)
        return 2
    cfg = load_config(Path(args.config))
    notes = scan_tree(ROOT, report, args.max_notes)
    exact_groups, fuzzy_groups = group_duplicates(notes)
    for group in fuzzy_groups:
        report.near_duplicates.append(' ~ '.join(str(n.path.relative_to(ROOT)) for n in group[:4]))
    consolidate(exact_groups, args.apply, cfg, report)
    retire_notes(notes, args.apply, report)
    normalize_frontmatter_only(notes, args.apply, cfg, report)
    drop_empty_dirs(ROOT, args.apply, report)
    refresh_index(ROOT, cfg, args.apply, report)
    Path(args.report).write_text(report.render(), encoding='utf-8')
    print(f'done. scanned={report.counts.get("scanned", 0)} applied={args.apply}')
    return 0


if __name__ == '__main__':
    sys.exit(main(sys.argv[1:]))
